#!/bin/zsh
TMUX=/opt/homebrew/bin/tmux
[ -x "$TMUX" ] || TMUX=/usr/local/bin/tmux
send() {
  $TMUX send-keys -t $1 C-u; sleep 1
  $TMUX send-keys -t $1 "$2"; sleep 2
  $TMUX send-keys -t $1 Enter; sleep 2
  $TMUX send-keys -t $1 Enter; sleep 1
  echo "sent -> $1"
}
